insert into public.blog_posts (slug, title, category, author, read_mins, published_at, excerpt, intro, sections, quote) values
  ('turn-mehandi-hobby-into-business', 'How to turn a mehandi hobby into a full-time business', 'Career', 'Anjali R.', 6, '2026-08-12', 'From your first paid booking to a full wedding season — what actually works.', 'Most of our mehandi graduates start with family functions. The ones who go full-time do three things differently.', '[{"heading":"1. Build a portfolio before you charge","text":"Photograph every design in natural light, front and back of the hand. Twenty strong photos beat a hundred average ones."},{"heading":"2. Price by the hour, quote by the event","text":"Know your hourly number, then quote clients a single event price. It is easier for them to say yes."},{"heading":"3. Get listed where brides search","text":"Certified graduates can join the Syllabdosth professional network and receive booking requests directly."}]'::jsonb, 'Your first ten clients come from people who already know you. Your next hundred come from your portfolio.'),
  ('saree-draping-styles-wedding-season', '5 saree draping styles to know this wedding season', 'Trends', 'Meera T.', 4, '2026-09-02', 'The drapes clients are asking for most — and when to suggest each one.', 'Wedding season brings every kind of request. These five drapes cover most of them.', '[{"heading":"1. Classic Nivi drape","text":"Clean pleats and a neat pallu. Works with almost every fabric and is the safest choice for long ceremonies."},{"heading":"2. Gujarati seedha pallu","text":"The pallu comes to the front to show off heavy borders and embroidery."},{"heading":"3. Bengali-inspired drape","text":"A distinctive silhouette with broad pleats. Works well when you want a more traditional statement."},{"heading":"4. Contemporary open-pallu style","text":"A lighter, modern look that keeps the details of the saree visible."},{"heading":"5. Pre-pleated or structured drape","text":"For busy wedding days, a pre-pleated drape makes getting ready faster and keeps the look neat all day."}]'::jsonb, 'The best saree drape is one that complements the fabric, occasion and comfort of the person wearing it.'),
  ('nail-art-certification-worth-it', 'What actually makes a nail art certification worth it', 'Certification', 'Kavya S.', 5, '2026-09-18', 'Five questions to ask before you pay for any nail art course.', 'Not every certificate helps you get clients. Here is what to look for.', '[{"heading":"Is there graded practice?","text":"You should be assessed on real sets, not just attendance."},{"heading":"Does it teach hygiene properly?","text":"Sterilisation and safe product use protect your clients and your reputation."},{"heading":"Does it lead to work?","text":"Look for courses that connect you with paying clients after you graduate."}]'::jsonb, null)
